// ❌ OLD: Shape-churning construction breaks hidden-class sharing.
// Adding each key one at a time forces a new Map transition and,
// in hot loops, can push the object into slow dictionary mode.
function makePoint(x, y, z) {
  const p = {}; // ❌ OLD: empty object — every subsequent add changes its shape
  p.x = x;
  p.y = y;
  p.z = z;
  return p;
}

const pts = [];
for (let i = 0; i < 1_000_000; i++) {
  pts.push(makePoint(i, i + 1, i + 2));
}

// Summing reads x from objects that each went through 3 shape
// transitions; the load site can't specialize to one Map.
let total = 0;
for (const p of pts) total += p.x; // ❌ OLD: likely megamorphic load
console.log(total);

// ✅ NEW: Construct the object with all keys in one literal so every
// instance shares a single hidden class (Map). The property load site
// stays monomorphic and TurboFan emits a MapCheck + direct offset load.
function makePoint(x, y, z) {
  // ✅ NEW: one literal → one Map transition → all points share the shape
  return { x, y, z };
}

const pts = [];
for (let i = 0; i < 1_000_000; i++) {
  pts.push(makePoint(i, i + 1, i + 2));
}

let total = 0;
for (const p of pts) total += p.x; // ✅ NEW: monomorphic load — MapCheck + offset
console.log(total);
